// ── Proxy helpers ──────────────────────────────────────────────────────────────
const PROXY_URL = 'http://localhost:3001';
const TTS_TIMEOUT = 25000; // ms

/**
 * Call the local tts-proxy.js to synthesize one line of audio
 * @returns {Promise<Blob>} MP3 audio blob
 */
async function synthesize(text, voiceKey) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TTS_TIMEOUT);

  try {
    const resp = await fetch(`${PROXY_URL}/tts`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text, voice: voiceKey, format: 'mp3' }),
      signal: controller.signal,
    });

    clearTimeout(timer);

    if (!resp.ok) {
      let errMsg = '';
      try {
        const err = await resp.json();
        errMsg = err.error || '';
      } catch {}
      throw new Error(`TTS error ${resp.status}${errMsg ? ': ' + errMsg : ''}`);
    }

    const blob = await resp.blob();
    if (blob.size === 0) throw new Error('TTS returned empty audio');
    return blob;
  } catch (e) {
    clearTimeout(timer);
    if (e.name === 'AbortError') throw new Error('TTS request timed out — is tts-proxy.js running?');
    throw e;
  }
}

/**
 * Check if the TTS proxy is reachable
 */
export async function isProxyReachable() {
  try {
    const resp = await fetch(`${PROXY_URL}/voices`, { method: 'GET' });
    return resp.ok;
  } catch {
    return false;
  }
}

// ── Script generation (Qwen, direct HTTP — no proxy needed) ─────────────────
/**
 * Generate a dialogue script using 通义千问 (Qwen)
 */
export async function generateScript(topic, lang = 'zh', targetMinutes = 4) {
  if (!DASHSCOPE_KEY) {
    throw new Error('通义千问 API key missing. Add REACT_APP_DASHSCOPE_API_KEY to .env');
  }

  const langInstruction = lang === 'zh'
    ? '所有对话必须使用简体中文，词汇简单，适合10-14岁学生理解。'
    : 'The dialogue should be in clear, simple English appropriate for young students (ages 10-14).';

  const systemPrompt = `你是课堂播客剧本作家。你创作两位角色之间的简短教育对话：一位友好的老师和一位好奇的学生。

${langInstruction}

规则：
- 总对话时长约 ${targetMinutes} 分钟（口播约 ${targetMinutes * 250} 字）
- 老师（Anna）用简单的语言解释主题
- 学生（Bob）问一个真实学生会问的问题
- 保持句子简短自然
- 包含自然的对话填充词如"那么...","嗯...","对吧..."
- 老师听起来要鼓励和耐心
- 学生听起来要真正好奇
- 以简短的总结或要点结束

输出格式：只返回有效的JSON数组，无其他文字。每个项目有：
- "speaker": "Anna" 或 "Bob"
- "text": 对话文本（每句不超过50字）`;

  const userPrompt = `写一段关于"${topic}"的课堂播客对话。
老师角色：Anna
学生角色：Bob
生成约 ${targetMinutes} 分钟的对话。`;

  const response = await fetch(
    'https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions',
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${DASHSCOPE_KEY}`,
      },
      body: JSON.stringify({
        model: 'qwen-plus',
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt },
        ],
        temperature: 0.8,
        max_tokens: 600,
      }),
    }
  );

  if (!response.ok) {
    const err = await response.text();
    throw new Error(`通义千问 API error: ${response.status} — ${err}`);
  }

  const data = await response.json();
  const raw = data.choices?.[0]?.message?.content?.trim() || '';

  // Parse JSON from response
  let jsonStr = raw;
  const codeBlockMatch = raw.match(/```(?:json)?\n?([\s\S]*?)\n?```/);
  if (codeBlockMatch) jsonStr = codeBlockMatch[1];
  else {
    const arrMatch = raw.match(/\[[\s\S]*\]/);
    if (arrMatch) jsonStr = arrMatch[0];
  }

  try {
    return JSON.parse(jsonStr);
  } catch (e) {
    console.error('Failed to parse script JSON:', jsonStr.slice(0, 200));
    throw new Error('AI剧本生成失败，请重试。');
  }
}

// ── Audio combination ─────────────────────────────────────────────────────────
async function combineBlobs(blobs) {
  if (blobs.length === 0) throw new Error('No audio to combine');
  if (blobs.length === 1) return blobs[0];
  const buffers = await Promise.all(blobs.map(b => b.arrayBuffer()));
  const total = buffers.reduce((acc, buf) => acc + buf.byteLength, 0);
  const combined = new Uint8Array(total);
  let offset = 0;
  for (const buf of buffers) {
    combined.set(new Uint8Array(buf), offset);
    offset += buf.byteLength;
  }
  return new Blob([combined], { type: 'audio/mpeg' });
}

// ── Full podcast generation ─────────────────────────────────────────────────────
/**
 * Generate full podcast audio from a script array
 * @param {Array}  lines        - [{ speaker: 'Anna', text: 'Hello!' }]
 * @param {Object} voices       - { 'Anna': 'longanhuan', 'Bob': 'longanyang' }
 * @param {Function} onProgress  - Progress callback (0-100)
 */
export async function generatePodcast(lines, voices, onProgress) {
  const audioBlobs = [];
  const total = lines.length;

  for (let i = 0; i < total; i++) {
    const line = lines[i];
    const voiceKey = voices[line.speaker] || 'longanyang';

    onProgress?.(Math.round((i / total) * 90));

    try {
      const blob = await synthesize(line.text, voiceKey);
      audioBlobs.push(blob);
    } catch (e) {
      console.warn(`Audio failed for line ${i + 1} (${line.speaker}):`, e.message);
    }
  }

  onProgress?.(95);

  if (audioBlobs.length === 0) {
    throw new Error('All audio generation failed. Make sure tts-proxy.js is running.');
  }

  const combined = await combineBlobs(audioBlobs);
  onProgress?.(100);
  return combined;
}

// ── Episode storage (localStorage) ─────────────────────────────────────────────
export function saveEpisode(episode) {
  const episodes = getEpisodes();
  episodes.unshift(episode);
  localStorage.setItem('podcast_episodes', JSON.stringify(episodes.slice(0, 50)));
  return episodes;
}

export function getEpisodes() {
  try {
    return JSON.parse(localStorage.getItem('podcast_episodes') || '[]');
  } catch {
    return [];
  }
}

export function deleteEpisode(id) {
  const episodes = getEpisodes().filter(e => e.id !== id);
  localStorage.setItem('podcast_episodes', JSON.stringify(episodes));
  return episodes;
}
